import{_ as r,o as a,c as t,a2 as o}from"./chunks/framework.Boholvbs.js";const i="/docs/logo-light.svg",l="/docs/logo-dark.svg",f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function s(p,e,g,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<p><a href="https://jeowp.org/" target="_blank" rel="noreferrer"><img src="'+i+'" alt="JEO Maps" class="light-only"> <img src="'+l+'" alt="JEO Maps" class="dark-only"></a></p><p>The JEO WordPress geojournalism platform allows news organizations, bloggers and NGOs to publish news stories as layers of information on digital maps. With JEO, creating the interaction between data layers and contextual information is intuitive and interactive.</p><h2 id="jeo-plugin" tabindex="-1">JEO Plugin <a class="header-anchor" href="#jeo-plugin" aria-label="Permalink to &quot;JEO Plugin&quot;">​</a></h2><p>Features:</p><ul><li><a href="https://www.mapbox.com/" target="_blank" rel="noreferrer">Mapbox</a> and <a href="https://maplibre.org/" target="_blank" rel="noreferrer">MapLibre</a> maps</li><li><a href="https://visgl.github.io/react-map-gl/" target="_blank" rel="noreferrer">react-map-gl</a> library</li><li>Custom tile layers</li><li>Layer filtering options, allowing you to mix tile layer.</li><li>Geocoding WordPress posts using OpenStreetMap (Nominatim), supporting the post type <code>Post</code>, with extensibility for additional geocoders via hook.</li><li>Customizable marker icons that can be associated to categories, custom taxonomies or posts directly.</li><li>Map markers query integrated to posts query.</li><li>Support <a href="https://wpml.org/pt-br/" target="_blank" rel="noreferrer">WPML</a> and <a href="https://wordpress.org/plugins/polylang/" target="_blank" rel="noreferrer">Polylang</a> multilingual plugins</li><li>AI-powered georeferencing, bulk geolocation, and map generation (multiple AI providers)</li><li>AI-assisted map block (Minimap) with chat refinement and auto-generated layers</li><li>Stories Near You block with geolocation-based post discovery</li></ul><p>Projects using JEO:</p><ul><li><a href="https://plenamata.eco/" target="_blank" rel="noreferrer">Plenamata</a></li><li><a href="https://infoamazonia.org/" target="_blank" rel="noreferrer">InfoAmazonia</a></li><li><a href="https://pasifika.news/" target="_blank" rel="noreferrer">Pasifika EnviroNews</a></li><li><a href="https://www.ekuatorial.com/" target="_blank" rel="noreferrer">Ekuatorial</a></li><li><a href="https://www.mekongeye.com/" target="_blank" rel="noreferrer">MekongEye</a></li><li><a href="http://caci.cimi.org.br/" target="_blank" rel="noreferrer">Caci</a></li></ul><p><a href="./index-plugin">Read documentation</a> or <a href="https://wordpress.org/plugins/jeowp/" target="_blank" rel="noreferrer">See in Wordpress store</a></p><h2 id="jeo-wordpress-theme" tabindex="-1">JEO WordPress Theme <a class="header-anchor" href="#jeo-wordpress-theme" aria-label="Permalink to &quot;JEO WordPress Theme&quot;">​</a></h2><p><a href="https://infoamazonia.github.io/jeo-theme/" target="_blank" rel="noreferrer">Read the documentation</a></p>',10)])])}const u=r(n,[["render",s]]);export{f as __pageData,u as default};
